mapper.select:
SELECT
  order_product_id orderProductId,
  order_sn orderSn,
  goods_id goodsId,
  goods_name goodsName,
  goods_image goodsImage,
  activity_id activityId,
  activity_name activityName,
  activity_type activityType,
  coupon_id couponId,
  user_coupon_id userCouponId,
  couponName couponName,
  spec_values specValues,
  goods_show_price goodsShowPrice,
  activity_discount_amount activityDiscountAmount,
  promotion_discount_amount promotionDiscountAmount,
  goods_num goodsNum,
  is_single isSingle,
  flavor_name flavorName,
  flavor_value flavorValue,
  commodity_id commodityId,
  category_name categoryName,
  send_integral sendIntegral
FROM bz_order_product

  
    AND order_sn = #{record.orderSn}
  
  
    AND order_sn in
    
      #{orderSn}
    
  
  
    AND store_id = #{record.storeId}
  
  
    AND store_name like concat('%', #{record.storeName}, '%')
  
  
    AND member_id = #{record.memberId}
  
  
    AND goods_id = #{record.goodsId}
  
  
    and goods_name like concat('%', #{record.goodsName}, '%')
  
  
    and goods_image = #{record.goodsImage}
  
  
    and spec_values = #{record.specValues}
  
  
    and goods_show_price = #{record.goodsShowPrice}
  
  
    and goods_num = #{record.goodsNum}
  
  
    and activity_discount_amount = #{record.activityDiscountAmount}
  
  
    and activity_discount_detail = #{record.activityDiscountDetail}
  
  
    and platform_activity_amount = #{record.platformActivityAmount}
  
  
    and platform_voucher_amount = #{record.platformVoucherAmount}
  
  
    and money_amount = #{record.moneyAmount}
  
  
    and commission_rate = #{record.commissionRate}
  
  
    and commission_amount = #{record.commissionAmount}
  
  
    and attach_commission_amount = #{record.attachCommissionAmount}
  
  
    and spell_team_id = #{record.spellTeamId}
  
  
    and is_gift = #{record.isGift}
  
  
    and gift_id = #{record.giftId}
  
  
    and return_number = #{record.returnNumber}
  
  
    and is_comment = #{record.isComment}
  
  
    and comment_time = #{record.commentTime}
  
  
    and send_integral = #{record.sendIntegral}
